// Package handoff builds a verifiable handoff packet for AI coding sessions.
//
// The packet's central claim is that every line in it carries a checkpoint
// citation: nothing here is an unattributable assertion. That invariant is
// enforced mechanically by TestEveryItemIsCited in packet_test.go, across
// every registered extractor.
//
// The types in this file are a frozen contract. Three workstreams code against
// them concurrently, so changing a field after the freeze breaks work already
// in flight in other branches.
package handoff

import (
	"context"
	"time"

	apicheckpoint "github.com/entireio/cli/api/checkpoint"
)

// Section names. Renderers and the Databricks ingest lane both key on these
// strings, so they are part of the contract, not display text.
const (
	SectionIntent    = "intent"
	SectionOpenItems = "open_items"
	SectionDeadEnds  = "dead_ends"
	SectionSurface   = "surface"
	SectionStopped   = "stopped"
)

// Citation is the provenance of one Item. Every Item must carry at least one.
//
// Line is a transcript.jsonl offset and is populated only by the dead-end
// miner, which is the one extractor working at line granularity. It indexes
// compact-transcript coordinates (Checkpoint.CompactStart), never raw
// full.jsonl coordinates -- see Checkpoint.CompactStart for why that
// distinction destroys citations if confused.
type Citation struct {
	CheckpointID string `json:"checkpoint_id"`
	SessionIndex int    `json:"session_index"`
	Line         int    `json:"line,omitempty"`
}

// Item is one cited line of the packet.
type Item struct {
	Text  string     `json:"text"`
	Cites []Citation `json:"cites"`
}

// Section is one of the five parts of the packet.
//
// Note carries a degradation reason ("no session summaries in range", "graph
// degenerate: no_dependents"). A section that could not do its job reports it
// here rather than failing the command -- see Extractor.
type Section struct {
	Name  string `json:"name"`
	Items []Item `json:"items"`
	Note  string `json:"note,omitempty"`
}

// Packet is the whole handoff document. The JSON encoding of this type is a
// published interface: it is what `entire handoff --json` emits and what the
// Databricks ingest lane consumes on stdin.
type Packet struct {
	Repo        string    `json:"repo"`
	GeneratedAt time.Time `json:"generated_at"`
	Head        string    `json:"head_checkpoint_id"`
	Sections    []Section `json:"sections"`
}

// Checkpoint is one checkpoint's worth of already-loaded data.
//
// input.go assembles these once so that no extractor touches the checkpoint
// store: extractors are pure functions over this struct, which is what keeps
// their tests running in milliseconds against fixture bytes instead of needing
// a git repository.
//
// Ordered NEWEST FIRST.
type Checkpoint struct {
	ID           string
	SessionIndex int
	CreatedAt    time.Time
	Metadata     *apicheckpoint.Metadata // never nil
	Summary      *apicheckpoint.Summary  // MAY BE NIL -- no summary was generated
	FilesTouched []string
	Transcript   []byte // transcript.jsonl bytes; nil when unavailable

	// CompactStart is Metadata.GetCompactTranscriptStart(), resolved once here
	// so no extractor calls it twice.
	//
	// HasCompactStart == false means LEGACY -- read from line 0. It does not
	// mean "error".
	//
	// Never mix this with Metadata.GetTranscriptStart(), which indexes raw
	// full.jsonl. They are different coordinate systems, and using the wrong
	// one yields citations that point at the wrong line while still looking
	// perfectly valid.
	CompactStart    int
	HasCompactStart bool
}

// GraphRunner shells out to `entire graph`. It is an interface so tests inject
// a fake and --no-graph is a one-line bypass (Input.Graph == nil).
type GraphRunner interface {
	Run(ctx context.Context, args ...string) ([]byte, error)
}

// Input is everything an extractor may read.
type Input struct {
	Repo        string
	Head        string       // HEAD's Entire-Checkpoint trailer, or ""
	Checkpoints []Checkpoint // newest first
	Graph       GraphRunner  // nil when --no-graph
}

// Extractor produces one Section of the packet.
//
// Failure is a Note, not an error. An extractor that cannot do its job returns
// a Section with empty Items and a populated Note, and a nil error; the error
// return is reserved for genuine bugs. Partial packets are the product -- a
// packet that refuses to print because one section degraded is worse than
// useless to the agent that needs orienting.
type Extractor interface {
	Name() string
	Extract(ctx context.Context, in Input) (Section, error)
}

// cite builds the single-citation slice that most extractors need. Extractors
// working at line granularity build their own with a Line set.
//
// Centralising this is deliberate: `dupl` blocks CI at threshold 75, and five
// extractors each assembling a Section by hand is exactly the shape it fires
// on.
func cite(cp Checkpoint) []Citation {
	return []Citation{{CheckpointID: cp.ID, SessionIndex: cp.SessionIndex}}
}

// section assembles a Section, normalising the empty case so that a section
// with no items always carries an explanation rather than rendering as a
// silent blank.
func section(name string, items []Item, emptyNote string) Section {
	if len(items) == 0 {
		return Section{Name: name, Items: nil, Note: emptyNote}
	}
	return Section{Name: name, Items: items}
}

package handoff

// allExtractors is the wiring list: it names every extractor exactly once, in
// packet order.
//
// This file is written once and then never edited again. Each workstream
// implements its own constructor in its own file and deletes the matching stub
// in stubs.go, so no shared file is ever changed twice and the wiring cannot
// conflict during integration. Adding a section -- including one a curveball
// demands -- is a new file plus one stub deletion.
func allExtractors(noGraph bool) []Extractor {
	xs := []Extractor{
		newIntentExtractor(),
		newOpenItemsExtractor(),
		newDeadEndsExtractor(),
	}
	if !noGraph {
		xs = append(xs, newSurfaceExtractor())
	}
	return append(xs, newStoppedExtractor())
}

package handoff

import "context"

// Placeholder extractors for sections still in flight on another branch.
//
// Each returns an empty Section carrying a "not implemented" Note, so the
// command runs end-to-end from the first commit and every section is visibly
// accounted for rather than silently missing.
//
// WHEN YOU LAND YOUR REAL EXTRACTOR, DELETE ITS LINE BELOW. That deletion is
// the only edit you make outside your own files.
//
//	newDeadEndsExtractor -> Workstream B (deadends.go)
//	newSurfaceExtractor  -> Workstream B (surface.go), optional
type notImplemented struct{ name string }

func (n notImplemented) Name() string { return n.name }

func (n notImplemented) Extract(context.Context, Input) (Section, error) {
	return Section{Name: n.name, Note: "not implemented"}, nil
}

func newDeadEndsExtractor() Extractor { return notImplemented{SectionDeadEnds} }
func newSurfaceExtractor() Extractor  { return notImplemented{SectionSurface} }

