package handoff

import (
	"context"
	"strings"
)

// noSummariesNote is shared by every extractor that reads Summary, so the
// degradation reads identically wherever it surfaces.
const noSummariesNote = "no session summaries in range — run with more checkpoints"

type intentExtractor struct{}

func newIntentExtractor() Extractor { return intentExtractor{} }

func (intentExtractor) Name() string { return SectionIntent }

// Extract lists what each session set out to do, newest first.
//
// Near-duplicates are dropped because consecutive checkpoints in one sitting
// routinely share an intent, and repeating it three times pushes the older,
// more informative entries out of the reader's view.
func (intentExtractor) Extract(_ context.Context, in Input) (Section, error) {
	var items []Item
	seen := make(map[string]bool)

	for _, cp := range in.Checkpoints {
		// Summary is a pointer and is nil whenever no summary was generated.
		if cp.Summary == nil {
			continue
		}
		text := strings.TrimSpace(cp.Summary.Intent)
		if text == "" {
			continue
		}
		key := normalizeForDedupe(text)
		if seen[key] {
			continue
		}
		seen[key] = true
		items = append(items, Item{Text: text, Cites: cite(cp)})
	}

	return section(SectionIntent, items, noSummariesNote), nil
}

// normalizeForDedupe collapses case and internal whitespace so that two
// summaries differing only in formatting compare equal. Deliberately not
// cleverer than that: stemming or fuzzy matching would silently merge two
// genuinely different intents, and losing one is worse than showing both.
func normalizeForDedupe(s string) string {
	return strings.ToLower(strings.Join(strings.Fields(s), " "))
}

package handoff

import (
	"context"
	"path"
	"strings"
)

type openItemsExtractor struct{}

func newOpenItemsExtractor() Extractor { return openItemsExtractor{} }

func (openItemsExtractor) Name() string { return SectionOpenItems }

// Extract unions the open items across the range and marks the ones that a
// later checkpoint probably resolved.
//
// "Probably" is doing real work here, and the design turns on it: an item is
// annotated `(likely closed)` rather than deleted. A dropped promise is the
// exact failure this product exists to fix, so a heuristic is never allowed to
// remove a line -- only to add a hint. The reader keeps the final say.
//
// Checkpoints arrive newest first, so "a later checkpoint" means one earlier in
// the slice.
func (openItemsExtractor) Extract(_ context.Context, in Input) (Section, error) {
	var items []Item
	seen := make(map[string]bool)

	for i, cp := range in.Checkpoints {
		if cp.Summary == nil {
			continue
		}
		// Files touched by any strictly-later checkpoint.
		later := filesTouchedBefore(in.Checkpoints, i)

		for _, raw := range cp.Summary.OpenItems {
			text := strings.TrimSpace(raw)
			if text == "" {
				continue
			}
			key := normalizeForDedupe(text)
			if seen[key] {
				continue
			}
			seen[key] = true

			if mentionsAny(text, later) {
				text += " (likely closed)"
			}
			items = append(items, Item{Text: text, Cites: cite(cp)})
		}
	}

	return section(SectionOpenItems, items, noSummariesNote), nil
}

// filesTouchedBefore collects files touched by checkpoints newer than index i.
// The slice is newest-first, so those are the entries at [0, i).
func filesTouchedBefore(cps []Checkpoint, i int) map[string]bool {
	files := make(map[string]bool)
	for _, cp := range cps[:i] {
		for _, f := range cp.FilesTouched {
			files[f] = true
			// Match on the base name too: an open item usually says
			// "recap_test.go", not the full repo-relative path.
			files[path.Base(f)] = true
		}
	}
	return files
}

// mentionsAny reports whether the item text names any of the given paths.
func mentionsAny(text string, files map[string]bool) bool {
	lower := strings.ToLower(text)
	for f := range files {
		if f == "" {
			continue
		}
		if strings.Contains(lower, strings.ToLower(f)) {
			return true
		}
	}
	return false
}

package handoff

import (
	"context"
	"fmt"
	"strings"
)

type stoppedExtractor struct{}

func newStoppedExtractor() Extractor { return stoppedExtractor{} }

func (stoppedExtractor) Name() string { return SectionStopped }

// Extract describes where the most recent session left off.
//
// Unlike the other sections this one reads the newest checkpoint only: it is a
// position report, not a history. It deliberately draws on metadata rather than
// the summary, so it still says something useful when no summary was generated
// -- which is the common case for a session that was interrupted, and exactly
// when a handoff matters most.
func (stoppedExtractor) Extract(_ context.Context, in Input) (Section, error) {
	if len(in.Checkpoints) == 0 {
		return section(SectionStopped, nil, "no checkpoints in range"), nil
	}
	cp := in.Checkpoints[0]
	cites := cite(cp)

	var items []Item
	add := func(format string, args ...any) {
		items = append(items, Item{Text: fmt.Sprintf(format, args...), Cites: cites})
	}

	if cp.Summary != nil {
		if outcome := strings.TrimSpace(cp.Summary.Outcome); outcome != "" {
			add("%s", outcome)
		}
	}

	if in.Head != "" {
		add("HEAD is at checkpoint %s", in.Head)
	}

	if md := cp.Metadata; md != nil {
		if len(md.FilesTouched) > 0 {
			add("Last touched: %s", strings.Join(limit(md.FilesTouched, 8), ", "))
		}
		if a := md.Attribution; a != nil && a.TotalLinesChanged > 0 {
			add("Attribution: %.0f%% agent across %d changed lines",
				a.AgentPercentage, a.TotalLinesChanged)
		}
		if m := md.SessionMetrics; m != nil && m.TurnCount > 0 {
			add("Session ran %d turns", m.TurnCount)
		}
		if t := md.TokenUsage; t != nil && t.OutputTokens > 0 {
			add("Tokens: %d in / %d out", t.InputTokens, t.OutputTokens)
		}
	}

	return section(SectionStopped, items, "no position data on the latest checkpoint"), nil
}

// limit caps a slice for display, appending an ellipsis entry when it truncates
// so the reader can tell the list is partial rather than complete.
func limit(xs []string, n int) []string {
	if len(xs) <= n {
		return xs
	}
	out := make([]string, 0, n+1)
	out = append(out, xs[:n]...)
	return append(out, fmt.Sprintf("… +%d more", len(xs)-n))
}

package handoff

import (
	"context"
	"fmt"
	"time"
)

// Now is swappable so tests get a deterministic GeneratedAt.
var Now = time.Now

// Build runs every extractor and assembles the packet.
//
// One extractor failing never fails the packet: its section is rendered with an
// "(unavailable: ...)" note and the rest still print. An agent that gets four
// good sections is oriented; one that gets an error message is not.
func Build(ctx context.Context, in Input, noGraph bool) Packet {
	p := Packet{
		Repo:        in.Repo,
		GeneratedAt: Now().UTC(),
		Head:        in.Head,
	}
	for _, x := range allExtractors(noGraph) {
		sec, err := x.Extract(ctx, in)
		if err != nil {
			sec = Section{Name: x.Name(), Note: fmt.Sprintf("unavailable: %v", err)}
		}
		if sec.Name == "" {
			sec.Name = x.Name()
		}
		p.Sections = append(p.Sections, sec)
	}
	return p
}

package handoff

import (
	"fmt"
	"io"
	"strings"
)

// sectionTitles are the human headings. The machine-readable names in the JSON
// packet stay stable regardless of what we call them here.
var sectionTitles = map[string]string{
	SectionIntent:    "What we were trying to do",
	SectionOpenItems: "Still open",
	SectionDeadEnds:  "Already tried — don't repeat",
	SectionSurface:   "Blast radius",
	SectionStopped:   "Where it stopped",
}

// RenderMarkdown writes the packet as markdown.
//
// No TTY dependence: no pager, no colour, no width probing. The output is
// identical piped and interactive, because the primary reader is an agent that
// has no terminal.
func RenderMarkdown(w io.Writer, p Packet) error {
	b := &strings.Builder{}

	fmt.Fprintf(b, "# Handoff — %s\n\n", p.Repo)
	fmt.Fprintf(b, "Generated %s", p.GeneratedAt.Format("2006-01-02 15:04 MST"))
	if p.Head != "" {
		fmt.Fprintf(b, " · HEAD checkpoint `%s`", p.Head)
	}
	b.WriteString("\n")

	for _, sec := range p.Sections {
		title := sectionTitles[sec.Name]
		if title == "" {
			title = sec.Name
		}
		fmt.Fprintf(b, "\n## %s\n\n", title)

		if len(sec.Items) == 0 {
			note := sec.Note
			if note == "" {
				note = "nothing recorded"
			}
			fmt.Fprintf(b, "_%s_\n", note)
			continue
		}
		for _, item := range sec.Items {
			fmt.Fprintf(b, "- %s %s\n", item.Text, formatCites(item.Cites))
		}
		if sec.Note != "" {
			fmt.Fprintf(b, "\n_%s_\n", sec.Note)
		}
	}

	_, err := io.WriteString(w, b.String())
	return err
}

// formatCites renders the provenance suffix. Every item has at least one
// citation by contract, so this is never empty in practice -- but it degrades
// quietly rather than panicking if that ever stops being true.
func formatCites(cites []Citation) string {
	if len(cites) == 0 {
		return ""
	}
	parts := make([]string, 0, len(cites))
	for _, c := range cites {
		s := shortID(c.CheckpointID)
		if c.Line > 0 {
			s = fmt.Sprintf("%s:%d", s, c.Line)
		}
		parts = append(parts, s)
	}
	return "`[" + strings.Join(parts, " ") + "]`"
}

// shortID trims a checkpoint ID for display. The full ID stays in the JSON
// packet, which is what any tool follows up with.
func shortID(id string) string {
	const n = 8
	if len(id) <= n {
		return id
	}
	return id[:n]
}

package handoff

import (
	"encoding/json"
	"io"
)

// RenderJSON writes the machine-readable packet.
//
// This encoding is a published interface: it is what a fresh agent reads to
// bootstrap and what the Databricks ingest lane consumes on stdin. Adding a
// field is safe; renaming or removing one is a breaking change for both.
//
// Sections is normalised to a non-nil slice and every Section's Items to a
// non-nil array, so consumers can iterate without a null check -- a null where
// an array was expected is the classic way a downstream parser dies on the one
// packet that happened to have an empty section.
func RenderJSON(w io.Writer, p Packet) error {
	if p.Sections == nil {
		p.Sections = []Section{}
	}
	for i := range p.Sections {
		if p.Sections[i].Items == nil {
			p.Sections[i].Items = []Item{}
		}
	}
	enc := json.NewEncoder(w)
	enc.SetIndent("", "  ")
	return enc.Encode(p)
}

package handoff

import (
	"context"
	"sort"

	apicheckpoint "github.com/entireio/cli/api/checkpoint"
	"github.com/entireio/cli/internal/id"
)

// Store is the slice of the checkpoint store this package needs. Narrowing it
// to three methods keeps the extractors testable with a small fake instead of a
// real git repository.
type Store interface {
	List(ctx context.Context) ([]apicheckpoint.CheckpointInfo, error)
	Read(ctx context.Context, checkpointID id.CheckpointID) (*apicheckpoint.CheckpointSummary, error)
	ReadSessionContent(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*apicheckpoint.SessionContent, error)
}

// LoadOptions bounds the checkpoint walk.
type LoadOptions struct {
	Repo       string
	Head       string
	Limit      int    // max checkpoints; <= 0 means DefaultLimit
	Checkpoint string // start here instead of the newest
	Graph      GraphRunner
}

// DefaultLimit is how many checkpoints back we read when unbounded. Ten covers
// a working session without making the packet too long for an agent to act on.
const DefaultLimit = 10

// Load walks the store newest-first and assembles the Input.
//
// Per-checkpoint failures are skipped rather than fatal: a single unreadable
// checkpoint -- unpushed, pruned, or written by a newer CLI -- must not deny
// the caller the other nine.
func Load(ctx context.Context, store Store, opts LoadOptions) (Input, error) {
	in := Input{Repo: opts.Repo, Head: opts.Head, Graph: opts.Graph}

	infos, err := store.List(ctx)
	if err != nil {
		return in, err
	}
	// List order is not guaranteed; the whole contract is newest-first.
	sort.Slice(infos, func(i, j int) bool {
		return infos[i].CreatedAt.After(infos[j].CreatedAt)
	})

	if opts.Checkpoint != "" {
		infos = skipUntil(infos, opts.Checkpoint)
	}

	max := opts.Limit
	if max <= 0 {
		max = DefaultLimit
	}

	for _, info := range infos {
		if len(in.Checkpoints) >= max {
			break
		}
		if info.ListedStub {
			// Names-only remote-discovery entry with nothing hydrated behind it.
			continue
		}
		cp, ok := loadCheckpoint(ctx, store, info)
		if !ok {
			continue
		}
		in.Checkpoints = append(in.Checkpoints, cp)
	}
	return in, nil
}

// loadCheckpoint reads one checkpoint's session data. Reports false when there
// is nothing usable to contribute.
func loadCheckpoint(ctx context.Context, store Store, info apicheckpoint.CheckpointInfo) (Checkpoint, bool) {
	// Session 0 is the primary session; a checkpoint always has at least one.
	content, err := store.ReadSessionContent(ctx, info.CheckpointID, 0)
	if err != nil || content == nil {
		return Checkpoint{}, false
	}
	md := content.Metadata

	cp := Checkpoint{
		ID:           info.CheckpointID.String(),
		SessionIndex: 0,
		CreatedAt:    info.CreatedAt,
		Metadata:     &md,
		Summary:      md.Summary,
		FilesTouched: info.FilesTouched,
		Transcript:   content.Transcript,
	}
	if len(cp.FilesTouched) == 0 {
		cp.FilesTouched = md.FilesTouched
	}

	// Resolve the compact-transcript offset exactly once here so no extractor
	// calls it twice and none reaches for GetTranscriptStart(), which indexes a
	// different file in a different coordinate system.
	cp.CompactStart, cp.HasCompactStart = md.GetCompactTranscriptStart()

	return cp, true
}

// skipUntil drops entries newer than the requested checkpoint, so --checkpoint
// reads "start the handoff here". An unknown ID yields the full list rather
// than an empty one: showing everything is a recoverable surprise, showing
// nothing looks like data loss.
func skipUntil(infos []apicheckpoint.CheckpointInfo, want string) []apicheckpoint.CheckpointInfo {
	for i, info := range infos {
		if info.CheckpointID.String() == want {
			return infos[i:]
		}
	}
	return infos
}

package handoff

import (
	"bytes"
	"context"
	"encoding/json"
	"strings"
	"testing"
	"time"

	apicheckpoint "github.com/entireio/cli/api/checkpoint"
)

func testInput() Input {
	md := &apicheckpoint.Metadata{
		FilesTouched: []string{"cmd/entire/cli/recap.go"},
	}
	return Input{
		Repo: "github.com/acme/cli",
		Head: "01JQ8Z9K2M3N4P5Q6R7S8T9V0W",
		Checkpoints: []Checkpoint{
			{
				ID:           "01JQ8Z9K2M3N4P5Q6R7S8T9V0W",
				SessionIndex: 0,
				CreatedAt:    time.Unix(1_757_000_000, 0),
				Metadata:     md,
				FilesTouched: []string{"cmd/entire/cli/recap.go"},
				Summary: &apicheckpoint.Summary{
					Intent:    "Add a --json flag to entire recap",
					Outcome:   "Flag added; tests still failing",
					OpenItems: []string{"recap_test.go still skips the empty-store case"},
				},
			},
			{
				ID:           "01AAAA9K2M3N4P5Q6R7S8T9V0W",
				SessionIndex: 0,
				CreatedAt:    time.Unix(1_756_000_000, 0),
				Metadata:     &apicheckpoint.Metadata{},
				Summary: &apicheckpoint.Summary{
					Intent:    "add a  --JSON flag to Entire recap", // near-duplicate
					OpenItems: []string{"document the packet shape"},
				},
			},
		},
	}
}

// TestEveryItemIsCited enforces the product's central claim mechanically across
// every registered extractor. If this fails, the packet is making assertions it
// cannot attribute, which is the one thing it must never do.
func TestEveryItemIsCited(t *testing.T) {
	t.Parallel()

	p := Build(context.Background(), testInput(), false)
	if len(p.Sections) == 0 {
		t.Fatal("packet has no sections")
	}
	for _, sec := range p.Sections {
		for i, item := range sec.Items {
			if len(item.Cites) == 0 {
				t.Errorf("section %q item %d (%q) has no citation", sec.Name, i, item.Text)
				continue
			}
			for _, c := range item.Cites {
				if c.CheckpointID == "" {
					t.Errorf("section %q item %d has an empty checkpoint ID", sec.Name, i)
				}
			}
		}
	}
}

// TestNilSummaryDoesNotPanic covers the most likely live failure: Summary is a
// pointer and is nil whenever no summary was generated, which is common for
// exactly the interrupted sessions a handoff is most needed for.
func TestNilSummaryDoesNotPanic(t *testing.T) {
	t.Parallel()

	in := Input{
		Repo: "r",
		Checkpoints: []Checkpoint{
			{ID: "01AAA", Metadata: &apicheckpoint.Metadata{}, Summary: nil},
			{ID: "01BBB", Metadata: &apicheckpoint.Metadata{}, Summary: nil},
		},
	}
	p := Build(context.Background(), in, false)

	for _, sec := range p.Sections {
		if sec.Name != SectionIntent && sec.Name != SectionOpenItems {
			continue
		}
		if len(sec.Items) != 0 {
			t.Errorf("section %q: want no items, got %d", sec.Name, len(sec.Items))
		}
		if sec.Note == "" {
			t.Errorf("section %q: empty section must carry a Note explaining why", sec.Name)
		}
	}

	// It must still render in both formats.
	if err := RenderMarkdown(&bytes.Buffer{}, p); err != nil {
		t.Fatalf("RenderMarkdown: %v", err)
	}
	if err := RenderJSON(&bytes.Buffer{}, p); err != nil {
		t.Fatalf("RenderJSON: %v", err)
	}
}

func TestEmptyInputStillProducesAPacket(t *testing.T) {
	t.Parallel()

	p := Build(context.Background(), Input{Repo: "r"}, false)
	if len(p.Sections) != 5 {
		t.Fatalf("want 5 sections, got %d", len(p.Sections))
	}
	for _, sec := range p.Sections {
		if sec.Note == "" {
			t.Errorf("section %q: empty section must carry a Note", sec.Name)
		}
	}
}

func TestNoGraphOmitsSurfaceSection(t *testing.T) {
	t.Parallel()

	p := Build(context.Background(), testInput(), true)
	for _, sec := range p.Sections {
		if sec.Name == SectionSurface {
			t.Fatal("--no-graph must omit the surface section")
		}
	}
}

func TestIntentDedupesNearDuplicates(t *testing.T) {
	t.Parallel()

	sec, err := newIntentExtractor().Extract(context.Background(), testInput())
	if err != nil {
		t.Fatalf("Extract: %v", err)
	}
	if len(sec.Items) != 1 {
		t.Fatalf("want 1 deduped intent, got %d: %+v", len(sec.Items), sec.Items)
	}
}

// TestOpenItemsMarksRatherThanDeletes pins the deliberate choice that a
// resolved-looking item is annotated, never dropped. Silently removing a
// promise is the failure this product claims to fix.
func TestOpenItemsMarksRatherThanDeletes(t *testing.T) {
	t.Parallel()

	in := Input{
		Checkpoints: []Checkpoint{
			{ // newer: touches the file the older item names
				ID:           "01NEW",
				Metadata:     &apicheckpoint.Metadata{},
				FilesTouched: []string{"cmd/entire/cli/recap_test.go"},
				Summary:      &apicheckpoint.Summary{},
			},
			{
				ID:       "01OLD",
				Metadata: &apicheckpoint.Metadata{},
				Summary: &apicheckpoint.Summary{
					OpenItems: []string{"recap_test.go still skips the empty-store case"},
				},
			},
		},
	}
	sec, err := newOpenItemsExtractor().Extract(context.Background(), in)
	if err != nil {
		t.Fatalf("Extract: %v", err)
	}
	if len(sec.Items) != 1 {
		t.Fatalf("item must be kept, not deleted; got %d items", len(sec.Items))
	}
	if !strings.Contains(sec.Items[0].Text, "(likely closed)") {
		t.Errorf("want a (likely closed) annotation, got %q", sec.Items[0].Text)
	}
}

// TestRenderJSONNeverEmitsNullArrays guards the published encoding: a null
// where a consumer expects an array is how a downstream parser dies on the one
// packet that happened to have an empty section.
func TestRenderJSONNeverEmitsNullArrays(t *testing.T) {
	t.Parallel()

	var buf bytes.Buffer
	if err := RenderJSON(&buf, Build(context.Background(), Input{Repo: "r"}, false)); err != nil {
		t.Fatalf("RenderJSON: %v", err)
	}
	if bytes.Contains(buf.Bytes(), []byte(": null")) {
		t.Errorf("packet contains a null array:\n%s", buf.String())
	}

	// And it must round-trip.
	var got Packet
	if err := json.Unmarshal(buf.Bytes(), &got); err != nil {
		t.Fatalf("round-trip: %v", err)
	}
	if got.Repo != "r" {
		t.Errorf("Repo = %q, want %q", got.Repo, "r")
	}
}

