func handoffRepoName(ctx context.Context) string {
	forge, owner, repo, err := gitremote.ResolveRemoteRepo(ctx, "origin")
	if err == nil && owner != "" && repo != "" {
		if forge != "" {
			return fmt.Sprintf("%s/%s/%s", forge, owner, repo)
