// with no items always carries an explanation rather than rendering as a
// silent blank.
func section(name string, items []Item, emptyNote string) Section {
	if len(items) == 0 {
		return Section{Name: name, Items: nil, Note: emptyNote}
	}
	return Section{Name: name, Items: items}
}

// emptyNoteFor picks the reason a summary-reading section came back empty,
// distinguishing "there was nothing to read" from "what we read had no
// summaries" so the note points at the actual cause.
func emptyNoteFor(in Input, reason string) string {
	if len(in.Checkpoints) == 0 {
		return noCheckpointsNote
	}
	return reason
}

