package handoff

import (
	"bytes"
	"encoding/json"
	"strings"
)

const (
	statusError   = "error"
	statusSuccess = "success"
)

type toolCall struct {
	Line     int
	Name     string
	Input    map[string]any
	Status   string
	Output   string
	Followup string
}

type transcriptLine struct {
	Type    string          `json:"type"`
	ID      string          `json:"id"`
	Content json.RawMessage `json:"content"`
}

type contentBlock struct {
	Type   string          `json:"type"`
	Text   string          `json:"text"`
	Name   string          `json:"name"`
	Input  map[string]any  `json:"input"`
	Result json.RawMessage `json:"result"`
}

type toolResult struct {
	Output string `json:"output"`
	Status string `json:"status"`
}

func scanToolCalls(transcript []byte, from int) []toolCall {
	if len(transcript) == 0 {
		return nil
	}
	lines := bytes.Split(transcript, []byte("\n"))
	if from > 0 && from < len(lines) {
		lines = lines[from:]
	}

	var calls []toolCall
	seen := make(map[string]bool)

	for i, raw := range lines {
		if len(bytes.TrimSpace(raw)) == 0 {
			continue
		}
		var tl transcriptLine
		if err := json.Unmarshal(raw, &tl); err != nil {
			continue
		}
		if tl.Type != "assistant" || len(tl.Content) == 0 {
			continue
		}
		var blocks []contentBlock
		if err := json.Unmarshal(tl.Content, &blocks); err != nil {
			continue
		}

		lineNo := from + i
		trailing := trailingText(blocks)

		for bi, b := range blocks {
			if b.Type != "tool_use" || len(b.Result) == 0 {
				continue
			}
			var res toolResult
			if err := json.Unmarshal(b.Result, &res); err != nil {
				continue
			}
			if res.Status != statusError {
				continue
			}
			if key := dedupeKey(tl.ID, bi); key != "" {
				if seen[key] {
					continue
				}
				seen[key] = true
			}
			calls = append(calls, toolCall{
				Line:     lineNo,
				Name:     b.Name,
				Input:    b.Input,
				Status:   res.Status,
				Output:   res.Output,
				Followup: trailing,
			})
		}
	}
	return calls
}

func dedupeKey(id string, blockIndex int) string {
	if id == "" {
		return ""
	}
	return id + ":" + itoa(blockIndex)
}

func itoa(n int) string {
	if n == 0 {
		return "0"
	}
	var b [20]byte
	i := len(b)
	neg := n < 0
	if neg {
		n = -n
	}
	for n > 0 {
		i--
		b[i] = byte('0' + n%10)
		n /= 10
	}
	if neg {
		i--
		b[i] = '-'
	}
	return string(b[i:])
}

func trailingText(blocks []contentBlock) string {
	for i := len(blocks) - 1; i >= 0; i-- {
		if blocks[i].Type == "text" {
			if t := strings.TrimSpace(blocks[i].Text); t != "" {
				return t
			}
		}
	}
	return ""
}

func groupKey(c toolCall) string {
	if c.Input != nil {
		for _, field := range []string{"command", "file_path", "path", "pattern"} {
			if v, ok := c.Input[field].(string); ok {
				if s := strings.TrimSpace(v); s != "" {
					return s
				}
			}
		}
	}
	if c.Name != "" {
		return c.Name
	}
	return "unknown tool"
}

package handoff

import (
	"context"
	"fmt"
	"sort"
	"strings"
)

const (
	maxDeadEnds      = 12
	maxOutputChars   = 200
	maxFollowupChars = 240
)

type deadEnd struct {
	Key      string
	Count    int
	Line     int
	Output   string
	Followup string
	Cite     Citation
}

type deadEndsExtractor struct{}

func newDeadEndsExtractor() Extractor { return deadEndsExtractor{} }

func (deadEndsExtractor) Name() string { return SectionDeadEnds }

func (deadEndsExtractor) Extract(_ context.Context, in Input) (Section, error) {
	if len(in.Checkpoints) == 0 {
		return section(SectionDeadEnds, nil, noCheckpointsNote), nil
	}

	byKey := make(map[string]*deadEnd)
	var order []string
	scanned := 0

	for _, cp := range in.Checkpoints {
		if len(cp.Transcript) == 0 {
			continue
		}
		start := 0
		if cp.HasCompactStart {
			start = cp.CompactStart
		}
		for _, c := range scanToolCalls(cp.Transcript, start) {
			scanned++
			key := groupKey(c)
			d, ok := byKey[key]
			if !ok {
				d = &deadEnd{
					Key:      key,
					Line:     c.Line,
					Output:   truncate(cleanWhitespace(c.Output), maxOutputChars),
					Followup: truncate(cleanWhitespace(c.Followup), maxFollowupChars),
					Cite: Citation{
						CheckpointID: cp.ID,
						SessionIndex: cp.SessionIndex,
						Line:         c.Line,
					},
				}
				byKey[key] = d
				order = append(order, key)
			}
			d.Count++
			if d.Followup == "" && c.Followup != "" {
				d.Followup = truncate(cleanWhitespace(c.Followup), maxFollowupChars)
			}
		}
	}

	if len(byKey) == 0 {
		if scanned == 0 && !anyTranscript(in) {
			return section(SectionDeadEnds, nil, "no transcripts available in range"), nil
		}
		return section(SectionDeadEnds, nil, "no failed tool calls found in range"), nil
	}

	ends := make([]*deadEnd, 0, len(byKey))
	for _, k := range order {
		ends = append(ends, byKey[k])
	}
	sort.SliceStable(ends, func(i, j int) bool {
		if ends[i].Count != ends[j].Count {
			return ends[i].Count > ends[j].Count
		}
		return ends[i].Line < ends[j].Line
	})

	var note string
	if len(ends) > maxDeadEnds {
		note = fmt.Sprintf("showing the %d most repeated of %d dead ends", maxDeadEnds, len(ends))
		ends = ends[:maxDeadEnds]
	}

	items := make([]Item, 0, len(ends))
	for _, d := range ends {
		items = append(items, Item{Text: d.describe(), Cites: []Citation{d.Cite}})
	}
	return Section{Name: SectionDeadEnds, Items: items, Note: note}, nil
}

func (d *deadEnd) describe() string {
	var b strings.Builder
	b.WriteString(d.Key)
	if d.Count > 1 {
		fmt.Fprintf(&b, " — failed %d times", d.Count)
	} else {
		b.WriteString(" — failed")
	}
	if d.Output != "" {
		fmt.Fprintf(&b, ": %s", d.Output)
	}
	if d.Followup != "" {
		fmt.Fprintf(&b, " (then: %s)", d.Followup)
	}
	return b.String()
}

func anyTranscript(in Input) bool {
	for _, cp := range in.Checkpoints {
		if len(cp.Transcript) > 0 {
			return true
		}
	}
	return false
}

func cleanWhitespace(s string) string {
	return strings.Join(strings.Fields(s), " ")
}

func truncate(s string, max int) string {
	if len(s) <= max {
		return s
	}
	cut := s[:max]
	if i := strings.LastIndexByte(cut, ' '); i > max/2 {
		cut = cut[:i]
	}
	return cut + "…"
}

