package main

import (
	"encoding/json"
	"strings"
	"time"
)

type Citation struct {
	CheckpointID string `json:"checkpoint_id"`
	SessionIndex int    `json:"session_index"`
	Line         int    `json:"line,omitempty"`
}

type Item struct {
	Text  string     `json:"text"`
	Cites []Citation `json:"cites"`
}

type Section struct {
	Name  string `json:"name"`
	Items []Item `json:"items"`
	Note  string `json:"note,omitempty"`
}

type Packet struct {
	Repo        string    `json:"repo"`
	GeneratedAt time.Time `json:"generated_at"`
	Head        string    `json:"head_checkpoint_id"`
	Sections    []Section `json:"sections"`
}

type Row struct {
	RepoKey      string    `json:"repo_key"`
	CheckpointID string    `json:"checkpoint_id"`
	SessionID    int       `json:"session_id"`
	HeadID       string    `json:"head_checkpoint_id"`
	GeneratedAt  time.Time `json:"generated_at"`
	SectionName  string    `json:"section_name"`
	ItemIndex    int       `json:"item_index"`
	ItemText     string    `json:"item_text"`
	CiteLine     int       `json:"cite_line"`
	SectionNote  string    `json:"section_note"`
	IngestedAt   time.Time `json:"ingested_at"`
}

func Flatten(p Packet, ingestedAt time.Time) []Row {
	var rows []Row
	repoKey := strings.TrimSpace(p.Repo)
	if repoKey == "" {
		repoKey = "unknown"
	}

	for _, sec := range p.Sections {
		if len(sec.Items) == 0 {
			rows = append(rows, Row{
				RepoKey:     repoKey,
				HeadID:      p.Head,
				GeneratedAt: p.GeneratedAt,
				SectionName: sec.Name,
				ItemIndex:   -1,
				SectionNote: sec.Note,
				IngestedAt:  ingestedAt,
			})
			continue
		}
		for i, item := range sec.Items {
			cites := item.Cites
			if len(cites) == 0 {
				cites = []Citation{{}}
			}
			for _, c := range cites {
				rows = append(rows, Row{
					RepoKey:      repoKey,
					CheckpointID: c.CheckpointID,
					SessionID:    c.SessionIndex,
					HeadID:       p.Head,
					GeneratedAt:  p.GeneratedAt,
					SectionName:  sec.Name,
					ItemIndex:    i,
					ItemText:     item.Text,
					CiteLine:     c.Line,
					SectionNote:  sec.Note,
					IngestedAt:   ingestedAt,
				})
			}
		}
	}
	return rows
}

func EncodeNDJSON(rows []Row) ([]byte, error) {
	var b strings.Builder
	enc := json.NewEncoder(&b)
	for _, r := range rows {
		if err := enc.Encode(r); err != nil {
			return nil, err
		}
	}
	return []byte(b.String()), nil
}

package main

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"os"
	"path"
	"path/filepath"
	"strings"
	"time"
)

const (
	filesAPIPath      = "/api/2.0/fs/files"
	statementsAPIPath = "/api/2.0/sql/statements"
	localHostScheme   = "file://"
	requestTimeout    = 60 * time.Second
)

type Config struct {
	Host        string
	Token       string
	WarehouseID string
	VolumePath  string
	Table       string
}

func ConfigFromEnv() (Config, error) {
	c := Config{
		Host:        strings.TrimSpace(os.Getenv("DATABRICKS_HOST")),
		Token:       strings.TrimSpace(os.Getenv("DATABRICKS_TOKEN")),
		WarehouseID: strings.TrimSpace(os.Getenv("DATABRICKS_WAREHOUSE_ID")),
		VolumePath:  strings.TrimSpace(os.Getenv("DATABRICKS_VOLUME_PATH")),
		Table:       strings.TrimSpace(os.Getenv("DATABRICKS_TABLE")),
	}
	if c.Table == "" {
		c.Table = "handoff_packets"
	}
	if c.Host == "" {
		return c, fmt.Errorf("DATABRICKS_HOST is required (use file:///path for local output)")
	}
	if c.IsLocal() {
		return c, nil
	}
	if c.Token == "" {
		return c, fmt.Errorf("DATABRICKS_TOKEN is required when DATABRICKS_HOST is a workspace URL")
	}
	if c.VolumePath == "" {
		return c, fmt.Errorf("DATABRICKS_VOLUME_PATH is required when DATABRICKS_HOST is a workspace URL")
	}
	return c, nil
}

func (c Config) IsLocal() bool { return strings.HasPrefix(c.Host, localHostScheme) }

func (c Config) LocalDir() string { return strings.TrimPrefix(c.Host, localHostScheme) }

type Uploader struct {
	cfg    Config
	client *http.Client
}

func NewUploader(cfg Config) *Uploader {
	return &Uploader{cfg: cfg, client: &http.Client{Timeout: requestTimeout}}
}

func objectName(p Packet, now time.Time) string {
	head := p.Head
	if head == "" {
		head = "nohead"
	}
	return fmt.Sprintf("%s-%d.json", sanitizeSegment(head), now.UTC().UnixNano())
}

func sanitizeSegment(s string) string {
	var b strings.Builder
	for _, r := range s {
		switch {
		case r >= 'a' && r <= 'z', r >= 'A' && r <= 'Z', r >= '0' && r <= '9', r == '-', r == '_':
			b.WriteRune(r)
		default:
			b.WriteByte('-')
		}
	}
	out := strings.Trim(b.String(), "-")
	if out == "" {
		return "unknown"
	}
	return out
}

func (u *Uploader) Upload(ctx context.Context, p Packet, payload []byte, now time.Time) (string, error) {
	name := objectName(p, now)
	repoDir := sanitizeSegment(p.Repo)

	if u.cfg.IsLocal() {
		dir := filepath.Join(u.cfg.LocalDir(), repoDir)
		if err := os.MkdirAll(dir, 0o755); err != nil {
			return "", fmt.Errorf("create local output dir: %w", err)
		}
		dest := filepath.Join(dir, name)
		if err := os.WriteFile(dest, payload, 0o600); err != nil {
			return "", fmt.Errorf("write local output: %w", err)
		}
		return dest, nil
	}

	remote := path.Join(u.cfg.VolumePath, repoDir, name)
	endpoint, err := u.endpoint(filesAPIPath + ensureLeadingSlash(remote))
	if err != nil {
		return "", err
	}
	req, err := http.NewRequestWithContext(ctx, http.MethodPut, endpoint, bytes.NewReader(payload))
	if err != nil {
		return "", err
	}
	req.Header.Set("Authorization", "Bearer "+u.cfg.Token)
	req.Header.Set("Content-Type", "application/octet-stream")

	resp, err := u.client.Do(req)
	if err != nil {
		return "", fmt.Errorf("upload to volume: %w", err)
	}
	defer resp.Body.Close()
	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
		return "", fmt.Errorf("upload to volume: %s: %s", resp.Status, readSnippet(resp.Body))
	}
	return remote, nil
}

func (u *Uploader) CopyInto(ctx context.Context, remotePath string) error {
	if u.cfg.IsLocal() {
		return nil
	}
	if u.cfg.WarehouseID == "" {
		return fmt.Errorf("DATABRICKS_WAREHOUSE_ID is required to run COPY INTO")
	}

	stmt := fmt.Sprintf(
		"COPY INTO %s FROM '%s' FILEFORMAT = JSON FORMAT_OPTIONS ('inferTimestamp' = 'true') COPY_OPTIONS ('mergeSchema' = 'false')",
		u.cfg.Table, path.Dir(ensureLeadingSlash(remotePath)),
	)
	body, err := json.Marshal(map[string]any{
		"statement":    stmt,
		"warehouse_id": u.cfg.WarehouseID,
		"wait_timeout": "30s",
	})
	if err != nil {
		return err
	}
	endpoint, err := u.endpoint(statementsAPIPath)
	if err != nil {
		return err
	}
	req, err := http.NewRequestWithContext(ctx, http.MethodPost, endpoint, bytes.NewReader(body))
	if err != nil {
		return err
	}
	req.Header.Set("Authorization", "Bearer "+u.cfg.Token)
	req.Header.Set("Content-Type", "application/json")

	resp, err := u.client.Do(req)
	if err != nil {
		return fmt.Errorf("copy into: %w", err)
	}
	defer resp.Body.Close()
	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
		return fmt.Errorf("copy into: %s: %s", resp.Status, readSnippet(resp.Body))
	}
	return nil
}

func (u *Uploader) endpoint(p string) (string, error) {
	base, err := url.Parse(strings.TrimSuffix(u.cfg.Host, "/"))
	if err != nil {
		return "", fmt.Errorf("parse DATABRICKS_HOST: %w", err)
	}
	if base.Scheme != "https" && base.Host != "127.0.0.1" && !strings.HasPrefix(base.Host, "127.0.0.1:") {
		return "", fmt.Errorf("DATABRICKS_HOST must use https")
	}
	return base.String() + p, nil
}

func ensureLeadingSlash(p string) string {
	if strings.HasPrefix(p, "/") {
		return p
	}
	return "/" + p
}

func readSnippet(r io.Reader) string {
	b, _ := io.ReadAll(io.LimitReader(r, 512))
	return strings.TrimSpace(string(b))
}

package main

import (
	"context"
	"encoding/json"
	"flag"
	"fmt"
	"io"
	"os"
	"time"
)

func main() {
	in := flag.String("in", "-", "packet JSON to read, or - for stdin")
	dryRun := flag.Bool("dry-run", false, "print the rows that would be sent and exit")
	flag.Parse()

	if err := run(context.Background(), *in, *dryRun, os.Stdout, os.Stderr); err != nil {
		fmt.Fprintln(os.Stderr, "handoff-databricks:", err)
		os.Exit(1)
	}
}

func run(ctx context.Context, in string, dryRun bool, stdout, stderr io.Writer) error {
	raw, err := readInput(in)
	if err != nil {
		return err
	}

	var p Packet
	if err := json.Unmarshal(raw, &p); err != nil {
		return fmt.Errorf("parse packet: %w", err)
	}

	now := time.Now().UTC()
	rows := Flatten(p, now)
	if len(rows) == 0 {
		fmt.Fprintln(stderr, "packet contained no sections; nothing to ingest")
		return nil
	}

	payload, err := EncodeNDJSON(rows)
	if err != nil {
		return fmt.Errorf("encode rows: %w", err)
	}

	if dryRun {
		_, err := stdout.Write(payload)
		return err
	}

	cfg, err := ConfigFromEnv()
	if err != nil {
		return err
	}

	u := NewUploader(cfg)
	dest, err := u.Upload(ctx, p, payload, now)
	if err != nil {
		return err
	}
	if err := u.CopyInto(ctx, dest); err != nil {
		return err
	}

	fmt.Fprintf(stderr, "ingested %d rows for %s -> %s\n", len(rows), p.Repo, dest)
	return nil
}

func readInput(in string) ([]byte, error) {
	if in == "-" || in == "" {
		return io.ReadAll(os.Stdin)
	}
	return os.ReadFile(in)
}

package main

